versions.variantCss:
.wemd-pullquote[data-variant="bytedance-pullquote-side"] {
  margin: 20px 0;
  padding: 0 0 0 20px;
  border-left: 3px solid var(--wemd-primary);
}
.wemd-pullquote[data-variant="bytedance-pullquote-side"] .wemd-component-body {
  padding: 0;
}
.wemd-pullquote[data-variant="bytedance-pullquote-side"] .wemd-component-body .wemd-child-1 {
  color: var(--wemd-text-strong);
  font-size: 17px;
  font-style: italic;
  font-weight: 500;
  line-height: 1.7;
  margin: 0;
}
